import itertools

def get_chromatic_number(N):
    # The graph is C_N x C_N with edges between (x,y) and (a,b) if
    # max(dist_N(x,a), dist_N(y,b)) == 1
    # where dist_N(x,a) = min(|x-a|, N - |x-a|)

    vertices = [(x, y) for x in range(N) for y in range(N)]
    adj = {v: [] for v in vertices}
    for i, v1 in enumerate(vertices):
        for j, v2 in enumerate(vertices):
            if i == j: continue
            x1, y1 = v1
            x2, y2 = v2
            dx = abs(x1 - x2)
            dy = abs(y1 - y2)
            dist_x = min(dx, N - dx)
            dist_y = min(dy, N - dy)
            if max(dist_x, dist_y) == 1:
                adj[v1].append(v2)

    # This is a small enough graph to try some coloring.
    # But for N=4, there are 16 vertices. For N=5, 25 vertices.
    # We want to find the chromatic number.
    # Let's just check if a k-coloring exists.

    def is_valid(coloring):
        for v in vertices:
            for neighbor in adj[v]:
                if coloring[v] == coloring[neighbor]:
                    return False
        return True

    def can_color(k):
        coloring = {}
        def backtrack(idx):
            if idx == len(vertices):
                return True
            v = vertices[idx]
            neighbor_colors = {coloring[nb] for nb in adj[v] if nb in coloring}
            for c in range(k):
                if c not in neighbor_colors:
                    coloring[v] = c
                    if backtrack(idx + 1):
                        return True
                    del coloring[v]
            return False
        return backtrack(0)

    for k in range(1, N*N + 1):
        if can_color(k):
            return k

