def get_adj_list(N):
    vertices = [(x, y) for x in range(N) for y in range(N)]
    adj = {v: [] for v in vertices}
    for v1 in vertices:
        x1, y1 = v1
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                x2 = (x1 + dx) % N
                y2 = (y1 + dy) % N
                adj[v1].append((x2, y2))
    return vertices, adj

def is_k_colorable(N, k):
    vertices, adj = get_adj_list(N)
    coloring = {}

    def backtrack(idx):
        if idx == len(vertices):
            return True
        v = vertices[idx]
        neighbor_colors = set()
